/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by compat/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Float, Sym, SymFunction, add, countOps, diff, exp, factor, fn, log, mul, pow, rational, simplify, symbols, trigsimp } from '../../src';
import { sympyStr } from '../sympy-str';

describe("doctests of sympy.vector.basisdependent", () => {
  it("diff(sin(x), x)", () => {
    const x = new Sym('x');
    expect(sympyStr(diff(fn('sin', [x]), x))).toBe('cos(x)');
  });
  it("diff(f(x), x, x, x)", () => {
    const x = new Sym('x');
    expect(sympyStr(diff(diff(diff((SymFunction('f'))(x), x), x), x))).toBe('Derivative(f(x), (x, 3))');
  });
  it("diff(f(x), x, 3)", () => {
    const x = new Sym('x');
    expect(sympyStr(diff((SymFunction('f'))(x), x, 3))).toBe('Derivative(f(x), (x, 3))');
  });
  it("diff(sin(x)*cos(y), x, 2, y, 2)", () => {
    const [y, x] = symbols('y x');
    expect(sympyStr(diff(diff(mul(fn('cos', [y]), fn('sin', [x])), x, 2), y, 2))).toBe('sin(x)*cos(y)');
  });
  it("diff(sin(x))", () => {
    const x = new Sym('x');
    const v1 = x;
    expect(sympyStr(diff(fn('sin', [v1]), v1))).toBe('cos(x)');
  });
  it("N(x, chop=True)", () => {
    expect(sympyStr(new Float(0.0001).evalf(15, { chop: true }))).toBe('0.000100000000000000');
  });
  it("N(x, chop=1e-5)", () => {
    expect(sympyStr(new Float(0.0001).evalf(15, { chop: 0.00001 }))).toBe('0.000100000000000000');
  });
  it("N(x, chop=1e-4)", () => {
    expect(sympyStr(new Float(0.0001).evalf(15, { chop: 0.0001 }))).toBe('0');
  });
  // the arguments do not type-check against the public API
  //   (x + y - z).subs(values)
  //   => 0
  it.todo("(x + y - z).subs(values)");
  // the arguments do not type-check against the public API
  //   (x + y - z).evalf(subs=values)
  //   => 1.00000000000000
  it.todo("(x + y - z).evalf(subs=values)");
  it("factor(2*x**5 + 2*x**4*y + 4*x**3 + 4*x**2*y + 2*x + 2*y)", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(factor(add(mul(2, x), mul(2, y), mul(2, pow(x, 5)), mul(4, pow(x, 3)), mul(2, y, pow(x, 4)), mul(4, y, pow(x, 2))), { deep: false, gaussian: false }))).toBe('2*(x + y)*(x**2 + 1)**2');
  });
  it("factor(x**2 + 1)", () => {
    const x = new Sym('x');
    expect(sympyStr(factor(add(1, pow(x, 2)), { deep: false, gaussian: false }))).toBe('x**2 + 1');
  });
  it("factor(x**2 + 1, modulus=2)", () => {
    const x = new Sym('x');
    expect(sympyStr(factor(add(1, pow(x, 2)), { modulus: 2n, deep: false, gaussian: false }))).toBe('(x + 1)**2');
  });
  it("factor(x**2 + 1, gaussian=True)", () => {
    const x = new Sym('x');
    expect(sympyStr(factor(add(1, pow(x, 2)), { deep: false, gaussian: true }))).toBe('(x - I)*(x + I)');
  });
  it("factor(x**2 - 2, extension=sqrt(2))", () => {
    const x = new Sym('x');
    expect(sympyStr(factor(add(-2, pow(x, 2)), { extension: [pow(2, rational(1, 2))], deep: false, gaussian: false }))).toBe('(x - sqrt(2))*(x + sqrt(2))');
  });
  it("factor((x**2 - 1)/(x**2 + 4*x + 4))", () => {
    const x = new Sym('x');
    expect(sympyStr(factor(mul(pow(add(4, pow(x, 2), mul(4, x)), -1), add(-1, pow(x, 2))), { deep: false, gaussian: false }))).toBe('(x - 1)*(x + 1)/(x + 2)**2');
  });
  it("factor((x**2 + 4*x + 4)**10000000*(x**2 + 1))", () => {
    const x = new Sym('x');
    expect(sympyStr(factor(mul(pow(add(4, pow(x, 2), mul(4, x)), 10000000), add(1, pow(x, 2))), { deep: false, gaussian: false }))).toBe('(x + 2)**20000000*(x**2 + 1)');
  });
  it("factor(eq)", () => {
    const x = new Sym('x');
    expect(sympyStr(factor(pow(2, add(1, pow(x, 2), mul(2, x))), { deep: false, gaussian: false }))).toBe('2**(x**2 + 2*x + 1)');
  });
  it("factor(eq, deep=True)", () => {
    const x = new Sym('x');
    expect(sympyStr(factor(pow(2, add(1, pow(x, 2), mul(2, x))), { deep: true, gaussian: false }))).toBe('2**((x + 1)**2)');
  });
  it("factor(5*x + 3*exp(2 - 7*x), deep=True)", () => {
    const x = new Sym('x');
    expect(sympyStr(factor(add(mul(3, exp(add(2, mul(-7, x)))), mul(5, x)), { deep: true, gaussian: false }))).toBe('(5*x*exp(7*x) + 3*exp(2))*exp(-7*x)');
  });
  it("factor(5*x + 3*exp(2 - 7*x), deep=True, fraction=False)", () => {
    const x = new Sym('x');
    expect(sympyStr(factor(add(mul(3, exp(add(2, mul(-7, x)))), mul(5, x)), { deep: true, gaussian: false, fraction: false }))).toBe('5*x + 3*exp(2)*exp(-7*x)');
  });
  it("simplify(a)", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(simplify(mul(pow(add(mul(x, pow(fn('cos', [y]), 2)), mul(x, pow(fn('sin', [y]), 2))), -1), add(x, pow(x, 2)))))).toBe('x + 1');
  });
  it("trigsimp(a)", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(trigsimp(mul(pow(add(mul(x, pow(fn('cos', [y]), 2)), mul(x, pow(fn('sin', [y]), 2))), -1), add(x, pow(x, 2))), { old: false, deep: false }))).toBe('(x**2 + x)/x');
  });
  it("simplify(root, ratio=1) == root", () => {
    expect(sympyStr(pow(add(3, pow(2, rational(1, 2))), -1).equals(pow(add(3, pow(2, rational(1, 2))), -1)))).toBe('True');
  });
  it("count_ops(g)", () => {
    const a = new Sym('a', { positive: true });
    const b = new Sym('b', { positive: true });
    expect(sympyStr(countOps(add(mul(log(a), log(pow(b, -1))), log(a), log(b))))).toBe('8');
  });
  it("count_ops(h)", () => {
    const a = new Sym('a', { positive: true });
    const b = new Sym('b', { positive: true });
    expect(sympyStr(countOps(log(mul(a, pow(b, add(1, mul(-1, log(a))))))))).toBe('5');
  });
  // text that is not a string
  //   print(count_ops(g, visual=True))
  //   => 2*ADD + DIV + 4*LOG + MUL
  it.todo("print(count_ops(g, visual=True))");
  // text that is not a string
  //   print(count_ops(h, visual=True))
  //   => 2*LOG + MUL + POW + SUB
  it.todo("print(count_ops(h, visual=True))");
  // no value
  //   simplify(g, measure=my_measure)
  //   => -log(a)*log(b) + log(a) + log(b)
  it.todo("simplify(g, measure=my_measure)");
  it("trigsimp(e)", () => {
    const x = new Sym('x');
    expect(sympyStr(trigsimp(add(mul(2, pow(fn('cos', [x]), 2)), mul(2, pow(fn('sin', [x]), 2))), { old: false, deep: false }))).toBe('2');
  });
  it("trigsimp(log(e))", () => {
    const x = new Sym('x');
    expect(sympyStr(trigsimp(log(add(mul(2, pow(fn('cos', [x]), 2)), mul(2, pow(fn('sin', [x]), 2)))), { old: false, deep: false }))).toBe('log(2)');
  });
  it("trigsimp(t, method='old') == t", () => {
    const x = new Sym('x');
    expect(sympyStr(add(mul(-2, pow(fn('coth', [x]), -7)), mul(3, pow(fn('tanh', [x]), 7))).equals(add(mul(-2, pow(fn('coth', [x]), -7)), mul(3, pow(fn('tanh', [x]), 7)))))).toBe('True');
  });
  it("trigsimp(t)", () => {
    const x = new Sym('x');
    expect(sympyStr(trigsimp(add(mul(-2, pow(fn('coth', [x]), -7)), mul(3, pow(fn('tanh', [x]), 7))), { old: false, deep: false }))).toBe('tanh(x)**7');
  });
  it("h", () => {
    const a = new Sym('a', { positive: true });
    const b = new Sym('b', { positive: true });
    expect(sympyStr(simplify(add(mul(log(a), log(pow(b, -1))), log(a), log(b))))).toBe('log(a*b**(1 - log(a)))');
  });
});
